# Python: Agent side - sign outgoing requests import hashlib, time, secrets, base64 from nacl.signing import SigningKey
def sign_request(method, url_path, body, domain, selector, key): t = str(int(time.time())) n = secrets.token_hex(8) body_hash = hashlib.sha256(body).hexdigest() signing_input = f"{domain}
{selector}
{t}
{n}
" signing_input += f"{method}
{url_path}
{body_hash}
" sig = key.sign(signing_input.encode()).signature sig_b64 = base64.b64encode(sig).decode().rstrip("=") return { "ApertoID-Signature": f"d={domain}; s={selector}; t={t}; n={n}; sig={sig_b64}" }
# Python: Verifier side - verify incoming requests def verify_request(request): header = request.headers.get("ApertoID-Signature") if not header: return "unsigned" tags = parse_tags(header) # extract d, s, t, n, sig # ... check timestamp, nonce, DNS lookup, then: body_hash = hashlib.sha256(request.body).hexdigest() signing_input = ( f"{tags['d']}
{tags['s']}
{tags['t']}
{tags['n']}
" f"{request.method}
{request.path}
{body_hash}
" ) pubkey = get_apertoid_pubkey(tags['d'], tags['s']) # DNS return verify_ed25519(pubkey, signing_input, tags['sig'])
